// This script is generated by Gemini
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;
using System.Collections; 

public class GameMenu : MonoBehaviour
{
    // Diğer scriptler buradan erişir: GameMenu.Instance.GameOver();
    public static GameMenu Instance { get; private set; }

    // Diğer scriptler oyunun akıp akmadığını buradan kontrol eder
    public static bool IsPlaying { get; private set; }

    // Giriş ekranı açık mı (MainMenuAmbience gibi scriptler kullanır)
    public static bool IsInMainMenu { get; private set; }

    // Play Again'e basılınca sahne yeniden yüklenir; bu bayrak ana menüyü atlatır
    static bool skipMainMenu = false;

    [Header("UI Panels")]
    [SerializeField] GameObject mainMenuPanel;  // Play / Quit
    [SerializeField] GameObject pauseMenuPanel; // Resume / Main Menu
    [SerializeField] GameObject gameOverPanel;  // Play Again / Main Menu
    [SerializeField] GameObject tutorialPanel;  // Nasıl oynanır + Back butonu
    [SerializeField] GameObject pauseBlur;      // Bulanıklık Volume'ü (opsiyonel)

    [Header("Audio - SFX")]
    [SerializeField] AudioSource gameOverAudio;
    [Tooltip("Drag the AudioSource containing the button click sound here")]
    [SerializeField] AudioSource uiClickAudio;
    [Tooltip("Drag the AudioSource containing the button hover sound here")]
    [SerializeField] AudioSource uiHoverAudio;

    [Header("Audio - Background Music")]
    [SerializeField] AudioSource menuMusic;
    [SerializeField] AudioSource gameMusic;
    [SerializeField] AudioSource gameOverMusic;

    enum State { MainMenu, Playing, Paused, GameOver, Tutorial }
    State state;

    void Awake()
    {
        Instance = this;
    }

    void Start()
    {
        // SFX setup: Allow UI sounds to play while game is paused
        if (gameOverAudio != null) gameOverAudio.ignoreListenerPause = true;
        if (uiClickAudio != null) uiClickAudio.ignoreListenerPause = true;
        if (uiHoverAudio != null) uiHoverAudio.ignoreListenerPause = true;

        // Music setup: Allow music to play even when the global AudioListener is paused
        if (menuMusic != null) menuMusic.ignoreListenerPause = true;
        if (gameMusic != null) gameMusic.ignoreListenerPause = true;
        if (gameOverMusic != null) gameOverMusic.ignoreListenerPause = true;

        if (skipMainMenu)
        {
            skipMainMenu = false;
            SetState(State.Playing);
        }
        else
        {
            SetState(State.MainMenu);
        }
    }

    void Update()
    {
        if (Keyboard.current == null || !Keyboard.current.escapeKey.wasPressedThisFrame)
            return;

        if (state == State.Playing) SetState(State.Paused);
        else if (state == State.Paused) SetState(State.Playing);
        else if (state == State.Tutorial) SetState(State.MainMenu);
        // Ana menüde ve oyun bitti ekranında ESC hiçbir şey yapmaz
    }

    // ----- Oyuncu kaybedince başka scriptten çağrılır -----
    public static event System.Action OnGameOver;

    public void GameOver()
    {
        if (state != State.Playing) return;

        if (gameOverAudio != null) gameOverAudio.Play();

        OnGameOver?.Invoke();   // Önce skorlar hesaplansın
        SetState(State.GameOver);
    }

    // ----- Butonlar ve Ses Tetikleyicileri -----

    public void PlayHoverSound()
    {
        if (uiHoverAudio != null) uiHoverAudio.Play();
    }

    private void PlayClickSound()
    {
        if (uiClickAudio != null) uiClickAudio.Play();
    }

    public void Play() 
    {
        PlayClickSound();
        SetState(State.Playing);
    }
    
    public void Resume() 
    {
        PlayClickSound();
        SetState(State.Playing);
    }

    public void OpenTutorial() 
    {
        PlayClickSound();
        SetState(State.Tutorial);
    }

    public void CloseTutorial() 
    {
        PlayClickSound();
        SetState(State.MainMenu);
    }

    public void PlayAgain()
    {
        PlayClickSound();
        skipMainMenu = true;   // Yeniden yüklenince doğrudan oyun başlasın
        StartCoroutine(DelayedReload());
    }

    public void MainMenu()
    {
        PlayClickSound();
        skipMainMenu = false;  // Yeniden yüklenince ana menü açılsın
        StartCoroutine(DelayedReload());
    }

    public void Quit()
    {
        PlayClickSound();
        StartCoroutine(DelayedQuit());
    }

    // ----- Coroutines for smooth sound transitions -----

    private IEnumerator DelayedReload()
    {
        yield return new WaitForSecondsRealtime(0.2f); 
        ReloadScene();
    }

    private IEnumerator DelayedQuit()
    {
        yield return new WaitForSecondsRealtime(0.2f);
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#else
        Application.Quit();
#endif
    }

    // ----- Yardımcılar -----

    void ReloadScene()
    {
        Time.timeScale = 1f;
        AudioListener.pause = false; 
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }

    void SetState(State newState)
    {
        state = newState;
        IsPlaying = state == State.Playing;
        IsInMainMenu = state == State.MainMenu;

        mainMenuPanel.SetActive(state == State.MainMenu);
        pauseMenuPanel.SetActive(state == State.Paused);
        gameOverPanel.SetActive(state == State.GameOver);
        if (tutorialPanel != null) tutorialPanel.SetActive(state == State.Tutorial);

        if (pauseBlur != null)
            pauseBlur.SetActive(state == State.Paused || state == State.GameOver);

        // Ses geçişlerini yönet
        UpdateMusic(newState);

        // Oyun sadece Playing durumunda akar
        Time.timeScale = IsPlaying ? 1f : 0f;
        AudioListener.pause = !IsPlaying; // Mutes in-game SFX like rain/footsteps
    }

    private void UpdateMusic(State newState)
    {
        // 1. Handle Game Music
        if (gameMusic != null)
        {
            if (newState == State.Playing)
            {
                if (!gameMusic.isPlaying) gameMusic.Play(); 
            }
            else
            {
                gameMusic.Pause(); 
            }
        }

        // 2. Handle Menu Music (Used for Main Menu, Pause Menu, and Tutorial)
        if (menuMusic != null)
        {
            if (newState == State.MainMenu || newState == State.Paused || newState == State.Tutorial)
            {
                if (!menuMusic.isPlaying) menuMusic.Play();
            }
            else
            {
                menuMusic.Stop(); 
            }
        }

        // 3. Handle Game Over Music
        if (gameOverMusic != null)
        {
            if (newState == State.GameOver)
            {
                if (!gameOverMusic.isPlaying) gameOverMusic.Play();
            }
            else
            {
                gameOverMusic.Stop();
            }
        }
    }
}